//! Ray class groups for arbitrary finite moduli and real-place conditions.
//!
//! The ray class group of a modulus `m` and a set `S` of real places is
//! `I_m / P_{m,S}`, where `I_m` is generated by ideals coprime to `m` and
//! `P_{m,S}` is generated by principal ideals `(alpha)` with `alpha = 1 mod m`
//! and `alpha` positive at every place in `S`. The exact sequence
//!
//! `1 -> (O/m)^* / image(U_S) -> Cl_m -> Cl -> 1`
//!
//! gives the ray class number. This module computes the finite quotient
//! `(O/m)^* / image(U_S)` explicitly for moduli whose norm is within a bounded
//! envelope, including its abelian invariants. When the ordinary class number
//! is one, the ray class group equals that quotient and the returned invariants
//! describe the full ray class group. For nontrivial class groups the full
//! extension invariants are not claimed, but the ray class number and the
//! congruence kernel invariants are exact.

#[allow(unused_imports)]
use crate::prelude::*;

use crate::collections::{BTreeMap, BTreeSet};
use crate::num::{Int, Rat};

use super::super::ratmatrix::{RatMatrix, rat_from_int};
use super::classgroup::class_group;
use super::embedding;
use super::ideal::Ideal;
use super::order::Order;
use super::units::unit_group;

/// A computed ray class group.
#[derive(Clone, Debug)]
pub(crate) struct RayClassGroup {
    order: Int,
    class_number: Int,
    kernel_invariants: Vec<Int>,
    invariants: Option<Vec<Int>>,
    real_places: Vec<usize>,
    residue_units: usize,
    image_order: Int,
    structure_certified: bool,
}

impl RayClassGroup {
    /// The ray class number.
    pub(crate) fn order(&self) -> &Int {
        &self.order
    }

    /// The ordinary class number.
    pub(crate) fn class_number(&self) -> &Int {
        &self.class_number
    }

    /// The abelian invariants of the congruence kernel `(O/m)^* / image(U_S)`.
    pub(crate) fn kernel_invariants(&self) -> &[Int] {
        &self.kernel_invariants
    }

    /// The full ray class group invariants, when they are certified.
    ///
    /// This is `Some` exactly when the ordinary class number is one, so the
    /// exact sequence splits trivially and `Cl_m` is the congruence kernel.
    pub(crate) fn invariants(&self) -> Option<&[Int]> {
        self.invariants.as_deref()
    }

    /// The selected real places.
    pub(crate) fn real_places(&self) -> &[usize] {
        &self.real_places
    }

    /// The number of units modulo the finite modulus.
    pub(crate) fn residue_units(&self) -> usize {
        self.residue_units
    }

    /// The order of the image of the allowed unit group.
    pub(crate) fn image_order(&self) -> &Int {
        &self.image_order
    }

    /// True when the full group structure, not only its order, is certified.
    pub(crate) fn structure_certified(&self) -> bool {
        self.structure_certified
    }
}

/// Compute the ray class group of a finite modulus and a set of real places.
///
/// Real place indices refer to the real embeddings in increasing root order.
/// The finite modulus may have several prime ideal factors. The residue ring
/// must have at most 200000 units and the congruence quotient at most 100000
/// elements; larger inputs return `None`.
pub(crate) fn ray_class_group(
    order: &Order,
    modulus: &Ideal,
    real_places: &[usize],
) -> Option<RayClassGroup> {
    let field = order.field();
    let real_count = field.signature().0;
    let mut places = real_places.to_vec();
    places.sort_unstable();
    places.dedup();
    if places.iter().any(|index| *index >= real_count) {
        return None;
    }
    let group = match class_group(order) {
        Some(v) => v,
        None => {
            return None;
        }
    };
    let class_number = group.class_number().clone();
    let units = unit_group(order)?;
    let residue = ResidueRing::new(order, modulus)?;
    if residue.size > 200_000 {
        return None;
    }
    let prime_factors = if modulus.norm().is_one() {
        Vec::new()
    } else {
        super::decomposition::factor_ideal(order, modulus)?
    };
    let mut residues = Vec::with_capacity(residue.size);
    for coordinates in residue.elements() {
        let is_unit = prime_factors
            .iter()
            .all(|(prime, _)| !prime.ideal().contains(&coordinates));
        if is_unit {
            residues.push(coordinates);
        }
    }
    let residue_units = residues.len();
    if residue_units == 0 {
        return None;
    }
    let generators = units.generators(order);
    let mut image = BTreeSet::new();
    let one_coordinates = order.coordinates_of(&field.one())?;
    let identity = residue.canonical(
        &one_coordinates
            .iter()
            .map(|value| value.num())
            .collect::<Vec<_>>(),
    );
    image.insert(identity.clone());
    let mut stack = Vec::new();
    let mut positive_generators = Vec::new();
    if generators.len() > 14 {
        return None;
    }
    for generator in &generators {
        positive_generators.push(generator.clone());
        positive_generators.push(order.field().multiply(generator, generator));
    }
    for mask in 0..(1usize << generators.len()) {
        let mut product = field.one();
        for (index, generator) in generators.iter().enumerate() {
            if mask & (1 << index) != 0 {
                product = field.multiply(&product, generator);
            }
        }
        positive_generators.push(product);
    }
    for generator in &positive_generators {
        let coordinates = order.coordinates_of(generator)?;
        if coordinates.iter().any(|value| !value.den().is_one()) {
            continue;
        }
        let allowed = places.iter().all(|index| {
            embedding::real_sign(order, generator, *index).is_some_and(|sign| sign > 0)
        });
        if !allowed {
            continue;
        }
        let integers: Vec<Int> = coordinates.iter().map(|value| value.num()).collect();
        let value = residue.canonical(&integers);
        if residue.is_unit(&value, &prime_factors, order) && image.insert(value.clone()) {
            stack.push(value);
        }
    }
    while let Some(current) = stack.pop() {
        for generator in &image.clone() {
            let product = residue.multiply(order, &current, generator);
            if image.insert(product.clone()) {
                stack.push(product);
            }
        }
        if image.len() > 200_000 {
            return None;
        }
    }
    let image_order = Int::from_u64(image.len() as u64);
    let ray_order = class_number
        .mul(&Int::from_u64(residue_units as u64))
        .divrem(&image_order)
        .ok()?
        .0;
    let complete = Int::from_u64(residue_units as u64)
        .divrem(&image_order)
        .ok()?
        .1;
    if !complete.is_zero() || !modulus.norm().is_one() && prime_factors.is_empty() {
        return None;
    }
    let quotient = quotient_group(order, &residue, &residues, &image)?;
    let (kernel_invariants, structure_certified, invariants) = if class_number.is_one() {
        (
            quotient.invariants.clone(),
            true,
            Some(quotient.invariants.clone()),
        )
    } else {
        (quotient.invariants, false, None)
    };
    let kernel_order = kernel_invariants
        .iter()
        .fold(Int::one(), |product, value| product.mul(value));
    if kernel_order != quotient.order {
        return None;
    }
    Some(RayClassGroup {
        order: ray_order,
        class_number,
        kernel_invariants,
        invariants,
        real_places: places,
        residue_units,
        image_order,
        structure_certified,
    })
}

struct Quotient {
    order: Int,
    invariants: Vec<Int>,
}

fn quotient_group(
    order: &Order,
    residue: &ResidueRing,
    units: &[Vec<Int>],
    image: &BTreeSet<Vec<Int>>,
) -> Option<Quotient> {
    let mut coset_of: BTreeMap<Vec<Int>, usize> = BTreeMap::new();
    let mut representatives = Vec::new();
    let one_coordinates = order.coordinates_of(&order.field().one())?;
    let identity = residue.canonical(
        &one_coordinates
            .iter()
            .map(|value| value.num())
            .collect::<Vec<_>>(),
    );
    let mut ordered: Vec<&Vec<Int>> = units.iter().collect();
    ordered.sort_by_key(|value| if *value == &identity { 0 } else { 1 });
    for unit in ordered {
        if coset_of.contains_key(unit) {
            continue;
        }
        let id = representatives.len();
        representatives.push(unit.clone());
        for element in image {
            let product = residue.multiply(order, unit, element);
            coset_of.insert(product, id);
        }
        if representatives.len() > 100_000 {
            return None;
        }
    }
    let size = representatives.len();
    let mut table = vec![vec![0usize; size]; size];
    for left in 0..size {
        for right in 0..size {
            let product = residue.multiply(order, &representatives[left], &representatives[right]);
            table[left][right] = *coset_of.get(&product)?;
        }
    }
    let invariants = abelian_invariants(&table, size)?;
    Some(Quotient {
        order: Int::from_u64(size as u64),
        invariants,
    })
}

#[allow(clippy::needless_range_loop)]
fn abelian_invariants(table: &[Vec<usize>], size: usize) -> Option<Vec<Int>> {
    if size == 0 {
        return None;
    }
    if size == 1 {
        return Some(Vec::new());
    }
    let factors = crate::numbertheory::factor_u64(size as u64);
    let mut invariants = Vec::new();
    for (prime, exponent) in factors {
        let prime = prime as usize;
        let mut counts = vec![0usize];
        let mut power = 1usize;
        for _ in 0..exponent {
            power *= prime;
            let mut count = 0usize;
            for element in 0..size {
                let mut current = element;
                for _ in 1..power {
                    current = table[current][element];
                }
                if current == 0 {
                    count += 1;
                }
            }
            counts.push(count);
        }
        let mut logs = vec![0usize];
        for count in &counts[1..] {
            let mut value = *count;
            let mut log = 0usize;
            while value > 1 {
                if value % prime != 0 {
                    return None;
                }
                value /= prime;
                log += 1;
            }
            if value != 1 {
                return None;
            }
            logs.push(log);
        }
        let max = *logs.last()?;
        for level in 1..=max {
            let below = logs.get(level - 1).copied().unwrap_or(0);
            let here = logs[level];
            let above = logs.get(level + 1).copied().unwrap_or(here);
            let multiplicity = (here - below).saturating_sub(above - here);
            for _ in 0..multiplicity {
                invariants.push(Int::from_i64(prime as i64).pow_u32(level as u32));
            }
        }
    }
    invariants.sort_by(|left, right| left.cmp(right));
    let product = invariants
        .iter()
        .fold(Int::one(), |value, entry| value.mul(entry));
    if product != Int::from_u64(size as u64) {
        return None;
    }
    Some(invariants)
}

struct ResidueRing {
    inverse: RatMatrix,
    basis: Vec<Vec<Int>>,
    size: usize,
}

impl ResidueRing {
    fn new(order: &Order, modulus: &Ideal) -> Option<Self> {
        let size = modulus.norm().to_i64()?;
        if size <= 0 {
            return None;
        }
        let basis = modulus.basis().to_vec();
        let matrix = RatMatrix::from_columns(
            basis
                .iter()
                .map(|column| column.iter().map(rat_from_int).collect())
                .collect(),
        )?;
        let inverse = matrix.inverse()?;
        let _ = order;
        Some(ResidueRing {
            inverse,
            basis,
            size: size as usize,
        })
    }

    fn canonical(&self, coordinates: &[Int]) -> Vec<Int> {
        let Some(column) =
            RatMatrix::from_columns(vec![coordinates.iter().map(rat_from_int).collect()])
        else {
            return coordinates.to_vec();
        };
        let Some(solution) = self.inverse.multiply(&column) else {
            return coordinates.to_vec();
        };
        let mut fractional = Vec::with_capacity(coordinates.len());
        for row in 0..solution.row_count() {
            let value = solution.get(row, 0);
            let floor = value.floor();
            fractional.push(
                value.sub(&Rat::from_ints(floor, Int::one()).unwrap_or_else(|_| Rat::zero())),
            );
        }
        let Some(frac_column) = RatMatrix::from_columns(vec![fractional]) else {
            return coordinates.to_vec();
        };
        let Some(basis) = RatMatrix::from_columns(
            self.basis
                .iter()
                .map(|column| column.iter().map(rat_from_int).collect())
                .collect(),
        ) else {
            return coordinates.to_vec();
        };
        let Some(mapped) = basis.multiply(&frac_column) else {
            return coordinates.to_vec();
        };
        let mut result = Vec::with_capacity(coordinates.len());
        for row in 0..mapped.row_count() {
            let value = mapped.get(row, 0);
            if value.den().is_one() {
                result.push(value.num());
            } else {
                return coordinates.to_vec();
            }
        }
        result
    }

    fn multiply(&self, order: &Order, left: &[Int], right: &[Int]) -> Vec<Int> {
        let product = order.multiply_coordinates(left, right);
        self.canonical(&product)
    }

    fn is_unit(
        &self,
        coordinates: &[Int],
        primes: &[(super::decomposition::PrimeIdeal, u32)],
        _order: &Order,
    ) -> bool {
        primes
            .iter()
            .all(|(prime, _)| !prime.ideal().contains(coordinates))
    }

    fn elements(&self) -> Vec<Vec<Int>> {
        let size = self.basis.len();
        let mut bound = 0i64;
        for row in 0..size {
            let mut total = 0i64;
            for column in &self.basis {
                total += column[row].to_i64().unwrap_or(0).abs();
            }
            bound = bound.max(total);
        }
        let width = (2 * bound + 1) as u128;
        if width.pow(size as u32) > 2_000_000 {
            return Vec::new();
        }
        let total = (2 * bound + 1).pow(size as u32);
        let mut seen = BTreeSet::new();
        let mut result = Vec::with_capacity(self.size);
        let mut coordinates = vec![Int::zero(); size];
        for code in 0..total {
            let mut code = code;
            for entry in &mut coordinates {
                let digit = code % (2 * bound + 1);
                code /= 2 * bound + 1;
                *entry = Int::from_i64(digit - bound);
            }
            let canonical = self.canonical(&coordinates);
            if seen.insert(canonical.clone()) {
                result.push(canonical);
                if result.len() == self.size {
                    break;
                }
            }
        }
        result
    }
}

#[cfg(test)]
mod tests {
    use super::super::classgroup::{class_group, ray_class_number, ray_class_number_real_places};
    use super::super::decomposition::decompose_prime_general;
    use super::super::field::NumberField;
    use super::super::integral_basis::maximal_order;
    use super::*;
    use crate::algebra::poly_z::ZPoly;

    fn poly(coefficients: &[i64]) -> ZPoly {
        ZPoly::new(
            coefficients
                .iter()
                .map(|value| Int::from_i64(*value))
                .collect(),
        )
    }

    fn field(coefficients: &[i64]) -> NumberField {
        NumberField::new(poly(coefficients)).unwrap()
    }

    #[test]
    fn general_modulus_agrees_with_prime_power_formula() {
        let quadratic = field(&[5, 0, 1]);
        let order = maximal_order(&quadratic).unwrap();
        let identity = Ideal::identity(&order).unwrap();
        let group = ray_class_group(&order, &identity, &[]).unwrap();
        assert_eq!(group.order(), class_group(&order).unwrap().class_number());
        assert_eq!(group.kernel_invariants().len(), 0);
        assert!(!group.structure_certified());

        let primes = decompose_prime_general(&order, &Int::from_i64(2)).unwrap();
        let modulus = primes[0].ideal();
        let group = ray_class_group(&order, modulus, &[]).unwrap();
        assert_eq!(group.order(), &ray_class_number(&order, modulus).unwrap());
    }

    #[test]
    fn multi_prime_modulus_and_kernel_invariants() {
        let quadratic = field(&[5, 0, 1]);
        let order = maximal_order(&quadratic).unwrap();
        let two = decompose_prime_general(&order, &Int::from_i64(2)).unwrap();
        let five = decompose_prime_general(&order, &Int::from_i64(5)).unwrap();
        let modulus = two[0].ideal().multiply(&order, five[0].ideal()).unwrap();
        let group = ray_class_group(&order, &modulus, &[]).unwrap();
        assert_eq!(group.order(), &Int::from_i64(4));
        assert_eq!(group.residue_units(), 4);
        assert_eq!(group.image_order(), &Int::from_i64(2));
        assert_eq!(group.kernel_invariants(), &[Int::from_i64(2)]);
        assert!(!group.structure_certified());
    }

    #[test]
    fn real_places_match_narrow_formula_for_quadratic_fields() {
        let quadratic = field(&[-5, 0, 1]);
        let order = maximal_order(&quadratic).unwrap();
        let identity = Ideal::identity(&order).unwrap();
        let group = ray_class_group(&order, &identity, &[0, 1]).unwrap();
        assert_eq!(group.order(), &Int::from_i64(1));
        assert!(group.invariants().is_some());
        let five = decompose_prime_general(&order, &Int::from_i64(5)).unwrap();
        let group = ray_class_group(&order, five[0].ideal(), &[0, 1]).unwrap();
        assert_eq!(
            group.order(),
            &ray_class_number_real_places(&order, five[0].ideal()).unwrap()
        );
    }

    #[test]
    fn trivial_class_group_gives_certified_structure() {
        let cyclotomic = field(&[1, 1, 1, 1, 1]);
        let order = maximal_order(&cyclotomic).unwrap();
        let identity = Ideal::identity(&order).unwrap();
        let group = ray_class_group(&order, &identity, &[]).unwrap();
        assert_eq!(group.order(), &Int::one());
        assert_eq!(group.invariants(), Some(&[][..]));
        assert!(group.structure_certified());
    }
}
